import{_ as a,o,c as r,a2 as t}from"./chunks/framework.Crpw6aS5.js";const s="/assets/01-og.DwB-JYz-.png",n="/assets/02-icon-512.C6eIqueJ.png",i="/assets/03-shot-dashboard.C3MLVNPu.png",l="/assets/04-shot-charts.CC2l0tFW.png",v=JSON.parse('{"title":"RevDash","description":"Imported note from https://revdash.me/","frontmatter":{"title":"RevDash","description":"Imported note from https://revdash.me/"},"headers":[],"relativePath":"obd2/related-projects/revdash-me.md","filePath":"obd2/related-projects/revdash-me.md"}'),d={name:"obd2/related-projects/revdash-me.md"};function h(p,e,c,u,g,m){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="revdash" tabindex="-1">RevDash <a class="header-anchor" href="#revdash" aria-label="Permalink to &quot;RevDash&quot;">​</a></h1><p>Site: <a href="https://revdash.me/" target="_blank" rel="noreferrer">revdash.me</a> · Product docs: <a href="https://revdash.me/docs" target="_blank" rel="noreferrer">revdash.me/docs</a> · Privacy: <a href="https://revdash.me/privacy" target="_blank" rel="noreferrer">revdash.me/privacy</a></p><p><img src="'+s+'" alt="RevDash open graph / brand banner"></p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><ul><li>Type: webpage</li><li>Origin: <a href="https://revdash.me/" target="_blank" rel="noreferrer">https://revdash.me/</a></li><li>Docs: <a href="https://revdash.me/docs" target="_blank" rel="noreferrer">https://revdash.me/docs</a></li><li>Privacy: <a href="https://revdash.me/privacy" target="_blank" rel="noreferrer">https://revdash.me/privacy</a></li><li>Imported: 2026-09-17</li></ul><h2 id="content" tabindex="-1">Content <a class="header-anchor" href="#content" aria-label="Permalink to &quot;Content&quot;">​</a></h2><p><strong>Every sensor your car already has, on your phone.</strong></p><p>Plug a cheap ELM327 into the OBD port, watch RPM, coolant, load and boost as you drive, and record the trip to the phone. Nothing leaves the phone until you upload a drive yourself; then you can replay the route in a browser, coloured by any parameter you logged.</p><table tabindex="0"><thead><tr><th>Highlight</th><th>Detail</th></tr></thead><tbody><tr><td>PIDs</td><td>108 known, plus your own CSV</td></tr><tr><td>Free cloud</td><td>20 trips a month, no card</td></tr><tr><td>Adapter</td><td>~£12 typical ELM327 (not sold by RevDash)</td></tr></tbody></table><p><img src="'+n+'" alt="RevDash app icon"></p><h3 id="an-adapter-a-phone-and-a-browser" tabindex="-1">An adapter, a phone, and a browser <a class="header-anchor" href="#an-adapter-a-phone-and-a-browser" aria-label="Permalink to &quot;An adapter, a phone, and a browser&quot;">​</a></h3><p>There is no box to fit, no subscription hardware, and no tracker wired into the loom. Parts are an adapter you can buy anywhere and a phone you already own.</p><ol><li><strong>Plug in the adapter</strong> — Any ELM327 over Bluetooth Classic, BLE, or Wi-Fi. RevDash tells you which protocol the car answered on.</li><li><strong>Build your dash</strong> — Drag the gauges you care about. Mode 01, VAG Mode 22 extras, or a community CSV you imported.</li><li><strong>Record the drive</strong> — Written to the phone as you go, with GPS if you allow it. Nothing leaves the device on its own.</li><li><strong>Replay in a browser</strong> — Upload when you want to, then scrub the route coloured by coolant, boost, speed, or whatever you logged.</li></ol><h3 id="a-dashboard-that-explains-itself" tabindex="-1">A dashboard that explains itself <a class="header-anchor" href="#a-dashboard-that-explains-itself" aria-label="Permalink to &quot;A dashboard that explains itself&quot;">​</a></h3><p>Most OBD apps fail in the car park with a spinner and no reason. RevDash tells “couldn’t reach the adapter” apart from “adapter fine, no ECU answering”, and says which one it hit.</p><p><img src="'+i+'" alt="RevDash live gauges dashboard screenshot"></p><ul><li><strong>Live gauges</strong> — RPM, speed, coolant, throttle, load, battery voltage, and whatever else in Mode 01 your ECU actually answers.</li><li><strong>VAG extras over Mode 22</strong> — Oil temperature, charge pressure actual and specified, torque, lambda, timing, rail pressure and wastegate, when a VW, Audi, SEAT or Škoda answers.</li><li><strong>A dash you arrange</strong> — Add, remove, drag and resize tiles. Each vehicle profile keeps its own layout and its own adapter.</li><li><strong>Check-engine, done carefully</strong> — Stored, pending and permanent codes with freeze frame and generic SAE titles, and a clear that asks before it does anything.</li><li><strong>Estimated gear</strong> — Derived from RPM and speed, so it works on a manual as well as an automatic.</li></ul><p><img src="'+l+'" alt="RevDash live charts screenshot"></p><h3 id="the-drive-not-a-summary-of-it" tabindex="-1">The drive, not a summary of it <a class="header-anchor" href="#the-drive-not-a-summary-of-it" aria-label="Permalink to &quot;The drive, not a summary of it&quot;">​</a></h3><p>A trip log is a wall of numbers. The replay puts those numbers back where they happened, so a reading you noticed becomes a corner you remember.</p><p>Example replay chrome from the marketing page: trip date, map overlay coloured by speed, play at 4×, distance / duration / max speed / peak coolant, plus CSV download.</p><ul><li><strong>The route on a real map</strong> — Photorealistic 3D globe, or a greyscale 2D map from the RevDash server. Switch at any time.</li><li><strong>Colour it by anything</strong> — Speed, coolant, boost, load; legend uses the real range of that parameter.</li><li><strong>Charts locked to the map</strong> — Scrub the trip and the marker follows. Brush a range on a chart and every chart zooms together.</li><li><strong>Play it back</strong> — 1×, 4×, 16× or 60×.</li><li><strong>Every value, downloadable</strong> — Full-resolution CSV of the whole trip.</li><li><strong>Works without a basemap</strong> — No map installed, or a drive with no GPS fix? The trip still opens; the charts still draw.</li></ul><h3 id="privacy-first" tabindex="-1">Privacy-first <a class="header-anchor" href="#privacy-first" aria-label="Permalink to &quot;Privacy-first&quot;">​</a></h3><p>Trips stay on the phone until you upload one, and a drive is only visible to anyone else if you make a link. Delete an account and the drives go with it.</p><ul><li>Generic OBD-II is powertrain only: no ABS, no airbags, no manufacturer body modules.</li><li>Nothing is written to the ECU except a code clear you confirm.</li><li>Cheap clones lie about their firmware; RevDash shows what yours actually reported.</li></ul><h3 id="free-vs-pro" tabindex="-1">Free vs Pro <a class="header-anchor" href="#free-vs-pro" aria-label="Permalink to &quot;Free vs Pro&quot;">​</a></h3><p>The app itself is free and works with no account. An account only matters when you want trips off the phone.</p><ul><li><strong>Free</strong> — Whole app without an account. Cloud: 20 trips a month, 30 days of history, CSV download and share links.</li><li><strong>Pro</strong> — Unlimited trips, kept indefinitely (pricing announced at launch).</li></ul><h3 id="what-revdash-does-not-do" tabindex="-1">What RevDash does not do <a class="header-anchor" href="#what-revdash-does-not-do" aria-label="Permalink to &quot;What RevDash does not do&quot;">​</a></h3><ul><li>Does not read ABS, airbag or body modules.</li><li>Does not write to the ECU or run actuator tests (except confirmed code clear).</li><li>Not a shop scan tool; not affiliated with any vehicle manufacturer.</li><li>Not Torque; uses no Torque branding or plugins.</li><li>No iPhone app (Android only). USB adapters are not supported.</li></ul><h3 id="faq-from-the-site" tabindex="-1">FAQ (from the site) <a class="header-anchor" href="#faq-from-the-site" aria-label="Permalink to &quot;FAQ (from the site)&quot;">​</a></h3><p><strong>Which adapter?</strong> Any ELM327-compatible: Bluetooth Classic, BLE, or Wi-Fi. No approved-hardware list. Wi-Fi dongles are their own AP — join in Android settings, then add in the app. USB not supported.</p><p><strong>Will it work on my car?</strong> Generic OBD-II powertrain: broadly petrol from 2001 and diesel from 2004 in the EU, and 1996 onward in the US. VW/Audi/SEAT/Škoda additionally answer Mode 22 (oil temp, charge pressure, etc.). RevDash only shows PIDs the ECU actually answered.</p><p><strong>Account?</strong> Not for gauges, codes, charts, layouts, or CSV export. Account is only so trips can leave the phone for browser replay.</p><p><strong>What gets uploaded?</strong> OBD readings you recorded and, if granted, GPS — only when you sign in and tap Upload. Not in the background.</p><p><strong>Free limit?</strong> Uploads stop at 20 trips/month; recording on the phone continues. Trips older than 30 days age out of free cloud history.</p><p><strong>Maps?</strong> 3D uses Google Maps tiles for the area you view. 2D comes from the RevDash server.</p><p><strong>Manual?</strong> <a href="https://revdash.me/docs" target="_blank" rel="noreferrer">https://revdash.me/docs</a> — adapters, dashboard, recording, custom PIDs, cloud replay, pointing Torque Pro at an upload URL.</p><h3 id="docs-overview-revdash-me-docs" tabindex="-1">Docs overview (revdash.me/docs) <a class="header-anchor" href="#docs-overview-revdash-me-docs" aria-label="Permalink to &quot;Docs overview (revdash.me/docs)&quot;">​</a></h3><p>The Android app is a live OBD-II dashboard. Recording is optional and stays on the phone until upload. Browser replay lives under <code>/app</code>.</p><p>Two “Torque-adjacent” features (unrelated to Torque branding):</p><ul><li><strong>Custom PIDs</strong> — community <code>extendedpids</code> CSV imported in the app.</li><li><strong>Torque Pro upload</strong> — point Torque’s “upload to webserver” at a RevDash-minted URL so those drives appear in the same trip list.</li></ul><p>Requirements: Android 8.0+, ELM327 Classic/BLE/Wi-Fi, generic powertrain OBD-II. No Android Auto build yet.</p><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ul><li>Privacy-first Android OBD-II dash: local recording by default; cloud upload is explicit.</li><li>Works with commodity ELM327 (Classic / BLE / Wi-Fi); shows real adapter/ECU failure modes instead of a silent spinner.</li><li>Browser trip replay colours the route by any logged parameter, with locked charts and full CSV export.</li><li>Honest limits: powertrain Mode 01 (+ VAG Mode 22 extras), no ABS/SRS, Android only, not a shop scan tool.</li></ul>',45)])])}const f=a(d,[["render",h]]);export{v as __pageData,f as default};
